/**
 * DNA OS — Architecture Health Report (DNA-000074)
 *
 * Reads registry/architecture-book.json + registry/module-registry.json
 * (already generated by scripts/build-arch-book.ts — this script does not
 * recompute anything build-arch-book.ts already computes, it only
 * synthesizes a report from that real data, per Rule 101/103).
 *
 * Writes registry/ARCHITECTURE_HEALTH_REPORT.json. Every number here is
 * derived directly from architecture-book.json's real fields — nothing is
 * estimated or guessed.
 */

import { readFileSync, writeFileSync, existsSync } from "fs";
import { join } from "path";

const ROOT = join(__dirname, "..");
const REGISTRY = join(ROOT, "registry");

function load(filename: string): any {
  const p = join(REGISTRY, filename);
  if (!existsSync(p)) throw new Error(`Missing ${filename} — run npx tsx scripts/build-arch-book.ts first`);
  return JSON.parse(readFileSync(p, "utf-8"));
}

interface ArchNode {
  id: string;
  type: string;
  status: "OK" | "BROKEN" | "UNUSED" | "UNREGISTERED";
  runtime_entry_point: boolean;
  internal_dependencies: string[];
  dependents: string[];
  data_tables: string[] | "UNKNOWN";
  business_capabilities: string[] | "UNKNOWN";
  domain_owner: string;
  lifecycle_status: string;
  deprecated: boolean;
}

function main() {
  const book = load("architecture-book.json");
  const moduleReg = load("module-registry.json");

  const moduleNodes: ArchNode[] = book.nodes.filter((n: any) => n.type === "Module");
  const total = moduleNodes.length;

  // ── Missing metadata ──
  const unknownCounts = {
    data_tables: moduleNodes.filter((n) => n.data_tables === "UNKNOWN").length,
    business_capabilities: moduleNodes.filter((n) => n.business_capabilities === "UNKNOWN").length,
    domain_owner: moduleNodes.filter((n) => n.domain_owner === "UNKNOWN").length,
    lifecycle_status: moduleNodes.filter((n) => n.lifecycle_status === "UNKNOWN").length,
  };

  // ── Duplicate registrations (same basename, multiple real paths) ──
  const keys: string[] = Object.keys(moduleReg.modules ?? {});
  const byBase: Record<string, string[]> = {};
  for (const k of keys) {
    const base = k.split("/").pop()!;
    (byBase[base] ||= []).push(k);
  }
  const duplicateRegistrations = Object.entries(byBase)
    .filter(([, v]) => v.length > 1)
    .map(([base, paths]) => ({ basename: base, paths }));

  // ── Orphan / dead modules ──
  const orphanModules = moduleNodes.filter((n) => n.status === "UNUSED").map((n) => n.id);
  const deadModules = moduleNodes.filter(
    (n) => n.status === "UNUSED" && !n.runtime_entry_point && n.dependents.length === 0
  ).map((n) => n.id);
  const unregisteredModules = moduleNodes.filter((n) => n.status === "UNREGISTERED").map((n) => n.id);

  // ── Circular dependencies (real DFS cycle detection on the import graph) ──
  const graph = new Map<string, string[]>();
  for (const n of moduleNodes) graph.set(n.id, n.internal_dependencies);

  const circular: string[][] = [];
  const visited = new Set<string>();
  const stack: string[] = [];
  const onStack = new Set<string>();

  function dfs(nodeId: string) {
    visited.add(nodeId);
    stack.push(nodeId);
    onStack.add(nodeId);
    for (const dep of graph.get(nodeId) ?? []) {
      if (!graph.has(dep)) continue; // dep outside module set (e.g. unresolved)
      if (onStack.has(dep)) {
        const cycleStart = stack.indexOf(dep);
        circular.push(stack.slice(cycleStart).concat(dep));
      } else if (!visited.has(dep)) {
        dfs(dep);
      }
    }
    stack.pop();
    onStack.delete(nodeId);
  }
  for (const n of moduleNodes) {
    if (!visited.has(n.id)) dfs(n.id);
  }
  // Dedupe cycles that are rotations of each other
  const seenCycles = new Set<string>();
  const uniqueCircular = circular.filter((cycle) => {
    const key = [...new Set(cycle)].sort().join("|");
    if (seenCycles.has(key)) return false;
    seenCycles.add(key);
    return true;
  });

  // ── Registry completeness % ──
  // A module is "complete" if none of its provable-or-UNKNOWN fields are UNKNOWN.
  // Fields that are structurally always UNKNOWN today (related_workflows etc.)
  // are excluded from this score — they're a known, stated gap (see
  // build-arch-book.ts's ArchNode comment), not a per-module data quality issue.
  const scoredFields = ["data_tables", "business_capabilities", "domain_owner", "lifecycle_status"] as const;
  let completeCount = 0;
  for (const n of moduleNodes) {
    const complete = scoredFields.every((f) => (n as any)[f] !== "UNKNOWN");
    if (complete) completeCount++;
  }
  const completenessPct = total > 0 ? Math.round((completeCount / total) * 10000) / 100 : 0;

  const report = {
    generated_at: new Date().toISOString(),
    source: "registry/architecture-book.json + registry/module-registry.json (via scripts/build-arch-book.ts)",
    total_modules: total,
    missing_metadata: {
      ...unknownCounts,
      note: "Counts of modules where the field could not be proven from source and was honestly marked UNKNOWN, not fabricated.",
    },
    duplicate_registrations: {
      count: duplicateRegistrations.length,
      entries: duplicateRegistrations,
    },
    orphan_modules: { count: orphanModules.length, entries: orphanModules },
    dead_modules: { count: deadModules.length, entries: deadModules },
    unregistered_modules: { count: unregisteredModules.length, entries: unregisteredModules },
    circular_dependencies: {
      count: uniqueCircular.length,
      cycles: uniqueCircular,
    },
    registry_completeness_pct: completenessPct,
    permanently_unknown_fields: [
      "related_workflows", "related_business_events", "related_documents",
      "related_commands", "related_services",
    ],
    permanently_unknown_reason: "No reliable mechanical link exists in this codebase today (registry/execution's domain-registry loaders have zero real importers per DNA-000024's own audit) — excluded from the completeness score rather than counted against every module or fabricated.",
  };

  const outPath = join(REGISTRY, "ARCHITECTURE_HEALTH_REPORT.json");
  writeFileSync(outPath, JSON.stringify(report, null, 2) + "\n", "utf-8");

  console.log("\nArchitecture Health Report");
  console.log(`  Total modules: ${total}`);
  console.log(`  Missing metadata (data_tables): ${unknownCounts.data_tables}`);
  console.log(`  Missing metadata (business_capabilities): ${unknownCounts.business_capabilities}`);
  console.log(`  Duplicate registrations: ${duplicateRegistrations.length}`);
  console.log(`  Orphan modules: ${orphanModules.length}`);
  console.log(`  Dead modules: ${deadModules.length}`);
  console.log(`  Unregistered modules: ${unregisteredModules.length}`);
  console.log(`  Circular dependencies: ${uniqueCircular.length}`);
  console.log(`  Registry completeness: ${completenessPct}%`);
  console.log(`  → ${outPath}`);
}

main();
